export ledger nullifierSet: Set<Field>;

// Verificación en circuit
export circuit vote(nullifier: Field) {
  assert(!nullifierSet.member(nullifier), "Ya ha votado");
  nullifierSet.insert(nullifier);
}

export circuit castVote(nullifier: Field) {
  // Verificar que el nullifier no existe
  assert(!nullifierSet.member(nullifier), "Double vote detected");

  // Registrar el nullifier
  nullifierSet.insert(nullifier);
}

export circuit spendToken(tokenNullifier: Field) {
  // Prevenir double-spending
  assert(
    !spentTokensSet.member(tokenNullifier),
    "Token already spent"
  );

  // Registrar como gastado
  spentTokensSet.insert(tokenNullifier);
}

