export struct Ballot {
  candidate: Field,
  nullifier: Field
}

export circuit castVote(ballot: Ballot) {
  // Verificar unicidad
  assert(!usedNullifiers.member(ballot.nullifier));

  // Registrar
  usedNullifiers.insert(ballot.nullifier);

  // Contar voto
  votes[ballot.candidate].increment(1);
}

export circuit claimAirdrop(
  eligibilityProof: Proof,
  nullifier: Field,
  recipient: Address
) {
  // Verificar elegibilidad
  assert(verifier.verify(eligibilityProof));

  // Verificar que no ha reclamado
  assert(!claimedNullifiers.member(nullifier));

  // Registrar y transferir
  claimedNullifiers.insert(nullifier);
  balances[recipient].transfer(airdropAmount);
}

export circuit validateAction(
  secretKey: witness<Field>,
  actionId: Field,
  nullifier: Field
) {
  // 1. Verificar generación correcta
  const computedNullifier = hash(secretKey, actionId);
  assert(nullifier == computedNullifier);

  // 2. Verificar que no existe
  assert(!nullifierSet.member(nullifier), "Acción ya realizada");
}

